vector<vector<long long>> apply_submatrix_adds(
    int n, int m, const vector<array<long long,5>>& ops) {
    vector<vector<long long>> diff(n + 1, vector<long long>(m + 1, 0));
    for (auto& op : ops) {
        int r1 = (int)op[0], c1 = (int)op[1], r2 = (int)op[2], c2 = (int)op[3];
        long long v = op[4];
        diff[r1][c1] += v;
        diff[r1][c2 + 1] -= v;
        diff[r2 + 1][c1] -= v;
        diff[r2 + 1][c2 + 1] += v;
    }
    vector<vector<long long>> result(n, vector<long long>(m, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            long long value = diff[i][j];
            if (i > 0) value += result[i - 1][j];
            if (j > 0) value += result[i][j - 1];
            if (i > 0 && j > 0) value -= result[i - 1][j - 1];
            result[i][j] = value;
        }
    }
    return result;
}

